<?php
require_once __DIR__.'/../includes/auth.php';$pdo=openDatabase();$user=requireLogin($pdo);requireRole($user,['Administrator']);$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$target=$id?findUserById($pdo,$id):false;if(!$target){http_response_code(404);exit('Account not found.');}$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrfToken($_POST);try{if(field('confirm')!=='yes')throw new InvalidArgumentException('Confirmation required.');if(field('action')==='delete')deleteAccount($pdo,(int)$user['user_id'],$id);elseif(field('action')==='access')changeAccess($pdo,(int)$user['user_id'],$id,field('role'),field('status'));else throw new InvalidArgumentException('Invalid action.');header('Location: manage-users.php',true,303);exit;}catch(Throwable $e){$error=$e;}}
pageStart('Manage account');if($error)showError($error);echo '<p>'.escapeHtml($target['full_name']).' — '.escapeHtml($target['email']).'</p>'; ?>
<form method="post"><?=csrfField()?><input type="hidden" name="action" value="access"><label>Role <select name="role"><?php foreach(['Student','Tutor','Administrator'] as $v):?><option <?=$target['role']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></label> <label>Status <select name="status"><?php foreach(['Active','Inactive'] as $v):?><option <?=$target['status']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></label> <label><input type="checkbox" name="confirm" value="yes" required> Confirm changes</label> <button class="btn btn-primary">Save access</button></form>
<hr><h2>Delete account</h2><p>Permanent deletion is blocked until retention policy is approved. Related requests must be retained.</p><form method="post"><?=csrfField()?><input type="hidden" name="action" value="delete"><label><input type="checkbox" name="confirm" value="yes" required> Confirm deletion request</label><button class="btn btn-danger">Confirm Delete</button></form><a href="manage-users.php">Cancel / Back</a><?php pageEnd(); ?>
